\begin{proof}
\label{eta2} We define $4$ random variables defined as 
\begin{equation*}
    X_i = \begin{cases}
        b_i & \text{with probability } p_i \\
        0 & \text{otherwise}
    \end{cases}
    \text{for } i=1,2,3,4.
\end{equation*}
We will require $b_1<b_2<b_3<b_4$ and $p_1=1$ (i.e $X_1=b_1$ always). The prophet value can be computed as 
\begin{equation*}
    \Ex{Z} = \sum_{1\leq i \leq 4} \pth{\prod_{i+1\leq j \leq 4} (1-p_j)} p_i b_i.
\end{equation*}
Next, we consider all possible algorithms for the instance. In total, we need to consider $6$ algorithms $\mathcal{A}_1, ..., \mathcal{A}_6$. 

$\mathcal{A}_1$ decides to accept $X_1$, and accept the next non-zero value it encounters (if any). Hence, the expected value it receives is 
\begin{equation*}
    \Ex{\mathcal{A}_1} = p_2b_2 + (1-p_2)p_3b_3 + (1-p_2)(1-p_3)p_4b_4 + (1-p_2)(1-p_3)(1-p_4)b_1. 
\end{equation*}
$\mathcal{A}_2$ decides to accept $X_1$, and accept the next non-zero value it encounters (if any) starting from $X_3$. Hence, the expected value it receives is 
\begin{equation*}
    \Ex{\mathcal{A}_2} = p_3b_3 + (1-p_3)p_4b_4 + (1-p_3)(1-p_4)b_1. 
\end{equation*}
$\mathcal{A}_3$ decides to accept $X_1$, and wait until $X_4$. Hence, the expected value it receives is 
\begin{equation*}
    \Ex{\mathcal{A}_3} = p_4b_4 + (1-p_4)b_1. 
\end{equation*}
$\mathcal{A}_4$ decides to wait until $X_3, X_4$ to use its 2 slots. Hence, the expected value it receives is 
\begin{equation*}
    \Ex{\mathcal{A}_4} = \Ex{\max(X_3, X_4)} =  p_4b_4 + (1-p_4)p_3 b_3. 
\end{equation*}
$\mathcal{A}_5$ skips $X_1$. It $X_2=0$, then it just gets the maximum of $X_3, X_4$. Otherwise, if $X_2>0$, then it accepts $X_2$, then it accepts the first non-zero value from $X_3, X_4$ (if any). Hence, the expected value it receives is 
\begin{equation*}
    \Ex{\mathcal{A}_5} = p_2 \left[ p_3b_3 + (1-p_3)p_4 b_4 + (1-p_3)(1-p_4)b_2 \right] + (1-p_2)\Ex{\mathcal{A}_4}. 
\end{equation*}
Finally, $\mathcal{A}_6$ skips $X_1$. If $X_2=0$, then it just gets the maximum of $X_3, X_4$. Otherwise, if $X_2>0$ it accepts $X_2$, then it waits for $X_4$ regardless of $X_3>0$. Hence, the expected value it receives is 
\begin{equation*}
    \Ex{\mathcal{A}_6} = p_2 \left[ p_4 b_4 + (1-p_4)b_2 \right] + (1-p_2)\Ex{\mathcal{A}_4}. 
\end{equation*}
Next, we set $b_i=c_i \beta$ for $i=1,2,3$ and $b_4=1$. We also set $p_1=1$ as mentioned earlier, and $p_4=c_4 \beta$. We then take the limit of $\Ex{\mathcal{A}_i}/\Ex{Z}$ as $\beta \to 0$. We get that the competitive ratios are 
\begin{align*}
    \alpha_1 = \lim_{\beta \to 0} \frac{\Ex{\mathcal{A}_1}}{\Ex{Z}} &= \frac{\left(c_2-c_4\right) p_2+c_1 \left(p_2-1\right) \left(p_3-1\right)+\left(c_4-c_3\right) \left(p_2-1\right) p_3+c_4}{c_1 \left(p_2-1\right) \left(p_3-1\right)-c_2 p_2 \left(p_3-1\right)+c_3 p_3+c_4} \\
    \alpha_2 = \lim_{\beta \to 0} \frac{\Ex{\mathcal{A}_2}}{\Ex{Z}} &= \frac{-\left(c_1-c_3+c_4\right) p_3+c_1+c_4}{c_1 \left(p_2-1\right) \left(p_3-1\right)-c_2 p_2 \left(p_3-1\right)+c_3 p_3+c_4}\\
    \alpha_3 = \lim_{\beta \to 0} \frac{\Ex{\mathcal{A}_3}}{\Ex{Z}} &= \frac{c_1+c_4}{c_1 \left(p_2-1\right) \left(p_3-1\right)-c_2 p_2 \left(p_3-1\right)+c_3 p_3+c_4}\\
    \alpha_4 = \lim_{\beta \to 0} \frac{\Ex{\mathcal{A}_4}}{\Ex{Z}} &= \frac{c_3 p_3+c_4}{c_1 \left(p_2-1\right) \left(p_3-1\right)-c_2 p_2 \left(p_3-1\right)+c_3 p_3+c_4} \\
    \alpha_5 = \lim_{\beta \to 0} \frac{\Ex{\mathcal{A}_5}}{\Ex{Z}} &= \frac{c_2 p_2+p_3 \left(c_3-\left(c_2+c_4\right) p_2\right)+c_4}{c_1 \left(p_2-1\right) \left(p_3-1\right)-c_2 p_2 \left(p_3-1\right)+c_3 p_3+c_4} \\
    \alpha_6 = \lim_{\beta \to 0} \frac{\Ex{\mathcal{A}_6}}{\Ex{Z}} &=  \frac{c_2 p_2-c_3 \left(p_2-1\right) p_3+c_4}{c_1 \left(p_2-1\right) \left(p_3-1\right)-c_2 p_2 \left(p_3-1\right)+c_3 p_3+c_4}
\end{align*}
Our objective is to determine the parameters $p_2, p_3, c_1, c_2, c_3, c_4$ that minimize $\max(\alpha_1, \alpha_2, \alpha_3, \alpha_4, \alpha_5, \alpha_6)$. By setting $c_1 = 1$, $c_2 = 2.04632458$, $c_3 = 2.9369093$, $c_4 = 0.8905847$, $p_2 = 0.4466646$, and $p_3 = 0.1487470$, we achieve a competitive ratio below $0.79424$. We verified these computations with the optimal dynamic program for this instance. 
\end{proof}
